      { q: "¿Cuántos espejos tiene un periscopio sencillo?", choices: ["1", "3", "2"], hint: "Uno arriba y otro abajo.", explain: "Un periscopio sencillo tiene 2 espejos, uno en cada punta del tubo." },
      { q: "¿Por qué los espejos de un periscopio están inclinados a 45°?", choices: ["Para que no se mojen", "Para que la luz doble una esquina de 90° en cada espejo", "Para que la imagen se vea al revés"], hint: "45° de entrada más 45° de salida.", explain: "A 45°, cada espejo hace girar la luz 90°, así que baja por el tubo y luego sale hacia tu ojo." },
      { q: "En un día sin viento, puedes ver las palmeras reflejadas en la laguna. ¿Por qué?", choices: ["El agua tranquila es lisa, así que refleja la luz como un espejo", "Los árboles están debajo del agua", "El agua hace su propia luz"], hint: "¿Qué tienen en común los espejos y el agua quieta?", explain: "El agua tranquila tiene la superficie lisa, así que refleja la luz de forma ordenada, como un espejo." }
